entries[357719] = { ["name"] = "Bansheeheulen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSylvanas stößt einen schrillen Schrei aus, der abhängig von der Gesundheit jedes anvisierten Spielercharakters Schaden verursacht. Beginnt mit [Quellwert] Schattenschaden bei voller Gesundheit und steigt auf 40072 Schattenschaden an. Dieser Schaden wird Spielercharakteren innerhalb von 4 Metern um jeden anvisierten Spielercharakter zugefügt. Betroffene Spielercharaktere werden für 6 Sek. unterbrochen.", ["unresolvedValues"] = true }
