entries[357726] = { ["name"] = "Schleier der Dunkelheit", ["text"] = "Unbegrenzte Reichweite\nSofort\nSylvanas hüllt einen Bereich in Nebel, verursacht 39937 Schattenschaden und befällt Gegner innerhalb einer tödlichen Wolke. Dabei werden 134268 Heilung absorbiert und alle 0,5 Sek. 1198 Schattenschaden verursacht.\n\n(100 - 75)% der gesamten Heilung umgeht diese Absorption.\nDieser Effekt beginnt bei 6 Stapeln und versucht pro Sekunde, 1 Stapel auf einen Spielercharakter innerhalb von 5 Metern zu übertragen." }
