entries[357732] = { ["name"] = "Ruf der Ewigkeit", ["text"] = "Sofort\nVerursacht 8 Sek. lang alle 2 Sek. 19968 Schattenschaden.\n\nDas Ziel explodiert beim Ablauf und fügt allen anderen Spielercharakteren innerhalb von 20 Metern 95848 Schattenschaden zu. Die Explosion hinterlässt ein Echo der Ewigkeit." }
