entries[358711] = { ["name"] = "Wut", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie dunkle Wache verfällt in blinde Wut, fixiert sich auf ein Ziel und greift keine anderen an. Die dunkle Wache erhält alle 4.5 Sek. zusätzliche Wut , was ihren verursachten Schaden um 10% erhöht und verhindert, dass sie auf weniger als 20% ihrer normalen Geschwindigkeit verlangsamt wird. Dieser Effekt ist stapelbar." }
entries[358712] = { ["name"] = "Annhyldes Aegis", ["text"] = "Sofort 1.5 min Abklingzeit\nSchützt Euch mit Annhyldes Aegis, die 8 Sek. lang den Schaden, den Ihr durch Gegner vor Euch erleidet, um 1799 verringert.\n\nWenn die Aegis mindestens 6297 Schaden absorbiert, wird sie überladen und stößt bei ihrem Ablauf gebündelte Macht aus, die allen Gegnern vor Euch 1003 Heiligschaden zufügt." }
entries[358713] = { ["name"] = "Wort des Rückrufs", ["text"] = "Sofort 1 min Abklingzeit\nVerringert die verbleibende Abklingzeit Eures passenden Heilzaubers um 3 Sek.\n\nGilt nur für Heilerspezialisierungen." }
