entries[358758] = { ["name"] = "Zerschmetterte Bestimmung", ["text"] = "Sofort\nUmgibt den Zaubernden mit einem Schild, der 8 Sek. lang bestehen bleibt und bis zu 1534494 Schaden absorbieren kann. Falls der Schild vor Ablauf seiner Dauer zerstört wird, erleidet der Zaubernde 6 Sek. lang 25% mehr Schaden." }
entries[358759] = { ["name"] = "Kiefers Himmelsgriff", ["text"] = "Unbegrenzte Reichweite\nSofort\nErhöht die Reichweite von 'Tigerklaue' auf 10 Meter und beim Einsatz springt Ihr sofort zum Ziel.\n\n'Tigerklaue' belegt das Ziel zusätzlich mit einem Effekt, der Eure kritische Trefferchance gegen das Ziel für 6 Sek. um 50% erhöht. Dieser Effekt kann pro Ziel nur einmal alle 1 Min. auftreten." }
entries[358760] = { ["name"] = "Zerrende Ketten", ["text"] = "200 Meter Reichweite\nWirken in 4 sek.\nDer stygische Entführer entfesselt Ketten auf sein Ziel sowie alle Spielercharaktere innerhalb von 6.5 Metern. Diese verursachen 47924 Schattenschaden, der gleichmäßig auf alle getroffenen Spielercharaktere aufgeteilt wird.\n\nZusätzlich beginnt der Entführer, alle getroffenen Ziele von der Plattform zu zerren. Die Kraft dieses Effekts wird verringert, je mehr Spielercharaktere angekettet wurden. Nachdem er 6 Sek. lang gezerrt hat, wird der Entführer vom Himmel geholt." }
entries[358761] = { ["name"] = "Öffnen", ["text"] = "Wirken in 1.5 sek.\nSchaltet den Zugang zu zusätzlichen Optionen für den rockenden Rennraseranpasser 19.9.3 frei." }
